import sys

def main():
    s = sys.stdin.read().split()[0]
    n = len(s)
    best = -1
    for first in (0, 1):
        mism = [(int(s[i]) != (first ^ (i & 1))) for i in range(n)]
        ok = True
        for i in range(n - 1):
            if mism[i] and mism[i + 1]:
                ok = False
                break
        if ok:
            c = sum(mism)
            if best < 0 or c < best:
                best = c
    print(best)

