    tests = ['0', '1', '00', '01', '11', '0100', '0110', '1111', '000', '010101', '101010', '0000', '1001', '00110']
    for n in range(1, 13):
        for _ in range(4):
            tests.append(''.join(rng.choice('01') for _ in range(n)))
    def near(n, k):
        first = rng.randint(0, 1)
        t = [(first ^ (i & 1)) for i in range(n)]
        spots = [x + i for i, x in enumerate(sorted(rng.sample(range(n - k + 1), k)))]
        for p in spots:
            t[p] ^= 1
        return ''.join(map(str, t))
    for n, k in ((11, 2), (12, 3), (13, 3), (14, 4), (30, 8), (31, 10)):
        tests.append(near(n, k))
    tests.append(near(10**5, 30000))
    tests.append(near(100000, 20000))
    tests.append(near(100000, 49999))
    tests.append(''.join(rng.choice('01') for _ in range(100000)))
    tests.append('0' * 100000)
    tests.append('01' * 50000)
    return tests

